import assert from 'node:assert/strict';
// test-style: fixture-read: Read only admission packets generated by the packaged provider against local fixture APIs.
import test from 'node:test';
import fs from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { packageReusableStaging } from './package-reusable-staging.mjs';
import { runManagedGateCommand as run } from './lib/managed-gate-command.mjs';
import { qualificationHash } from './lib/runtime-qualification-execution.mjs';
import {
  createStudioServerReleaseManifest,
  promoteStudioServerReleaseManifest,
} from './lib/studio-server-release-manifest.mjs';
import { fixture, settings, operation, actor, digest, wait } from './test-fixtures/reusable-staging.mjs';
import {
  cliDiscovery,
  assertFixtureRequest,
  nativeKubernetes,
  decodeKubernetesBody,
} from './test-fixtures/kubernetes-cli.mjs';
import { persistenceFixture } from './test-fixtures/persistence.mjs';
import { inspectStagingPrerequisites } from './lib/reusable-staging-prerequisites.mjs';
import { stagingCloudReader } from './lib/reusable-staging-cloud.mjs';

const rootDir = fileURLToPath(new URL('../../../', import.meta.url));
const evidence = { workflow: 'Build Images', runId: '123', runAttempt: 1 };
function providerOperation() {
  const make = (letter, predecessorRelease) =>
    createStudioServerReleaseManifest({
      rootDir,
      source: { repository: 'example/rivet', ref: 'refs/heads/main', sha: letter.repeat(40) },
      images: Object.fromEntries(
        ['proxy', 'web', 'api', 'executor'].map((role) => [
          role,
          { repository: `registry.test/${role}`, digest: `sha256:${letter.repeat(64)}` },
        ]),
      ),
      candidateEvidence: evidence,
      predecessorRelease,
    });
  const previous = promoteStudioServerReleaseManifest(make('a'), { promotionEvidence: evidence });
  const { inputHash, ...input } = operation();
  Object.assign(input, {
    previous,
    candidate: make('b', previous),
    qualification: { tier: 'focused' },
    startedAt: new Date().toISOString(),
    installed: {
      qualificationValues: {
        availability: {
          gkeGateway: true,
          gkeGatewayProfile: 'compact',
          podAntiAffinity: { enabled: true, required: true, topologyKey: 'kubernetes.io/hostname' },
          topologySpread: {
            enabled: true,
            topologyKey: 'topology.kubernetes.io/zone',
            nodeTaintsPolicy: 'Honor',
            whenUnsatisfiable: 'DoNotSchedule',
            maxSkew: 1,
            minDomains: 2,
          },
        },
        resources: {
          web: { requests: { cpu: '50m', memory: '128Mi' } },
          proxy: { requests: { cpu: '100m', memory: '128Mi' } },
        },
        postgres: { maxConnections: 250, reservedConnections: 30, poolMaxPerApiPod: 10 },
        legacyRestore: { enabled: true, size: '8Gi' },
      },
    },
  });
  return { ...input, inputHash: qualificationHash(input) };
}

for (const fault of ['none', 'admission', 'lost-ack', 'interrupt'])
  test(`packaged provider preparation and cleanup with native tools: ${fault}`, { timeout: 45000 }, async (t) => {
    const folder = await fs.mkdtemp(path.join(os.tmpdir(), 'rivet-provider-tools-'));
    t.after(() => fs.rm(folder, { recursive: true, force: true }));
    const previousEnv = process.env.KUBECONFIG;
    t.after(() => (previousEnv === undefined ? delete process.env.KUBECONFIG : (process.env.KUBECONFIG = previousEnv)));
    const previousCapture = process.env.RIVET_QUALIFICATION_RECEIPT_STDOUT;
    process.env.RIVET_QUALIFICATION_RECEIPT_STDOUT = '1';
    t.after(() =>
      previousCapture === undefined
        ? delete process.env.RIVET_QUALIFICATION_RECEIPT_STDOUT
        : (process.env.RIVET_QUALIFICATION_RECEIPT_STDOUT = previousCapture),
    );
    const op = providerOperation();
    const errors = [],
      admitted = [];
    const cancellation = new AbortController();
    let faultRequests = 0;
    const namespace = `rivet-staging-${op.operationId}`;
    const computePrefix = `projects/${settings().projectId}`;
    const backendPath = `${computePrefix}/regions/europe-central2/backendServices/fixture`;
    const healthPath = `${computePrefix}/global/healthChecks/fixture`;
    const selfLink = (resource) => `https://compute.googleapis.com/compute/v1/${resource}`;
    const computeObjects = new Map();
    const computeObject = (resource) => {
      if (!computeObjects.has(resource))
        computeObjects.set(resource, {
          id: String(100 + computeObjects.size),
          selfLink: selfLink(resource),
          creationTimestamp: new Date().toISOString(),
          ...(resource === backendPath
            ? {
                healthChecks: [selfLink(healthPath)],
                backends: ['a', 'b'].map((zone) => ({
                  group: selfLink(`${computePrefix}/zones/europe-central2-${zone}/networkEndpointGroups/fixture-neg`),
                })),
              }
            : {}),
        });
      return computeObjects.get(resource);
    };
    const f = await fixture(t, op, {
      decodeBody: decodeKubernetesBody,
      intercept(packet) {
        try {
          assertFixtureRequest(packet.req);
          if (packet.url.pathname.startsWith('/fixture-compute/')) {
            const { res, result, objects, url } = packet;
            if (!objects.has(`/api/v1/namespaces/${namespace}`)) {
              res.statusCode = 404;
              result({});
              return true;
            }
            const resource = url.pathname.split('/compute/v1/')[1];
            result(
              resource.endsWith('/aggregated/backendServices')
                ? {
                    items: { 'regions/europe-central2': { backendServices: [computeObject(backendPath)] } },
                  }
                : computeObject(resource),
            );
            return true;
          }
          if (cliDiscovery(packet)) return true;
          const { req, url, input, result, res } = packet;
          if (req.method === 'POST' && url.searchParams.get('dryRun') === 'All') {
            res.setHeader('Warning', '299 - "fixture resource adjustment"');
            assert.equal(input.kind === 'List', false, 'Native admission must send individual workloads');
            admitted.push(input);
            if (fault === 'admission') {
              faultRequests++;
              res.statusCode = 403;
              result({
                apiVersion: 'v1',
                kind: 'Status',
                reason: 'Forbidden',
                message: 'fixture admission denied',
                code: 403,
              });
              return true;
            }
            const output = structuredClone(input);
            output.spec.template.spec.containers[0].resources.requests.cpu = '500m';
            output.metadata.namespace ??= `rivet-staging-${op.operationId}`;
            res.statusCode = 201;
            result(output);
            return true;
          }
          if (
            req.method === 'POST' &&
            input.kind === 'Deployment' &&
            input.metadata.name === 'release-gate-minio' &&
            ['lost-ack', 'interrupt'].includes(fault)
          ) {
            faultRequests++;
            nativeKubernetes({ ...packet, result: () => {} }); // Commit, then lose the reply.
            if (fault === 'lost-ack') res.destroy();
            else cancellation.abort(new Error('fixture interrupted dependency creation'));
            return true;
          }
          return nativeKubernetes(packet);
        } catch (error) {
          errors.push(error);
          packet.res.statusCode = 500;
          packet.result({ message: error.message });
          return true;
        }
      },
      deleted({ current, objects }) {
        if (current.kind === 'Namespace')
          for (const [key, value] of objects)
            if (value.metadata.namespace === current.metadata.name || value.kind === 'PersistentVolume')
              objects.delete(key);
      },
    });
    Object.assign(f.objects.get('/api/v1/namespaces/kube-system'), { apiVersion: 'v1', kind: 'Namespace' });
    const kubeconfig = path.join(folder, 'kubeconfig.json');
    await fs.writeFile(
      kubeconfig,
      JSON.stringify({
        apiVersion: 'v1',
        kind: 'Config',
        clusters: [{ name: 'fixture', cluster: { server: f.origin } }],
        users: [],
        contexts: [{ name: settings().context, context: { cluster: 'fixture' } }],
        'current-context': settings().context,
      }),
    );
    process.env.KUBECONFIG = kubeconfig;
    const tools = {
      node: process.version,
      kubectl: JSON.parse(
        (
          await run(process.env.RIVET_K8S_KUBECTL_BIN || 'kubectl', ['version', '--client', '-o', 'json'], {
            capture: true,
          })
        ).stdout,
      ).clientVersion.gitVersion,
      helm: (
        await run(process.env.RIVET_K8S_HELM_BIN || 'helm', ['version', '--short'], { capture: true })
      ).stdout.trim(),
    };
    assert.equal(tools.node, 'v24.22.1', 'Use the qualification Node version');
    assert.match(tools.kubectl, /^v1\.36\.6(?:\+\S+)?$/);
    assert.match(tools.helm, /^v3\.22\.1(?:\+\S+)?$/);
    const output = path.join(folder, 'package');
    await packageReusableStaging({
      settings: settings(),
      output,
      janitorImage: `registry.test/janitor@sha256:${digest}`,
      googleServiceAccount: 'janitor@isolated-staging.iam.gserviceaccount.com',
    });
    const { ReusableProviderGate, executeProviderPhase, withManagedGateSignal, waitForManagedGateCommands } =
      await import(pathToFileURL(path.join(output, 'driver/provider.mjs')));
    const gate = new ReusableProviderGate(op, settings(), f.state, folder);
    const app = await persistenceFixture(t, { headers: () => gate.probeHeaders, key: () => gate.secrets.rivetKey });
    gate.config.baseUrl = app.origin;
    const positive = (type) => ({ type, status: 'True', observedGeneration: 1 });
    f.store(
      `/apis/gateway.networking.k8s.io/v1/namespaces/${settings().gatewayNamespace}/gateways/${settings().gatewayName}`,
      {
        metadata: { uid: settings().gatewayUid, generation: 1 },
        spec: {
          listeners: [
            {
              name: 'https',
              protocol: 'HTTPS',
              port: 443,
              hostname: `*.${settings().domain}`,
              allowedRoutes: {
                namespaces: {
                  from: 'Selector',
                  selector: { matchLabels: { 'rivet.dev/qualification-route': 'true' } },
                },
              },
            },
          ],
        },
        status: {
          addresses: [{ type: 'IPAddress', value: '192.0.2.200' }],
          conditions: [positive('Programmed')],
          listeners: [{ name: 'https', conditions: [positive('Accepted'), positive('ResolvedRefs')] }],
        },
      },
    );
    f.store(`/apis/storage.k8s.io/v1/storageclasses/${settings().storageClassName}`, {
      metadata: { uid: 'storage-uid' },
      provisioner: 'pd.csi.storage.gke.io',
      reclaimPolicy: 'Delete',
    });
    f.store('/apis/metrics.k8s.io/v1beta1/nodes', {
      metadata: {},
      items: [{ timestamp: new Date().toISOString(), usage: { cpu: '10m', memory: '100Ki' } }],
    });
    // Only the provider-only observations are substituted. Rendering, admission,
    // dependency/route creation, Helm install/waits, auth, seeding and cleanup use
    // the shipped implementations. This cannot prove real TLS/NEG/CSI health.
    gate.verifySharedPrerequisites = () => inspectStagingPrerequisites(f.state, { verifyTls: async () => {} });
    gate.readyPublic = async () => {
      await gate.loadWorkflowKey();
      await gate.waitForDeveloperRoute(app.origin);
      await gate.verifyClientProvenance();
    };
    const cloud = stagingCloudReader(settings(), {
      token: async () => 'local-test-only',
      fetchImpl: (url, options) => {
        assert.equal(new URL(url).hostname, 'compute.googleapis.com');
        return fetch(`${f.origin}/fixture-compute${new URL(url).pathname}`, options);
      },
    });
    const steps = [];
    const phase = (name) =>
      executeProviderPhase({
        phase: name,
        operation: op,
        state: f.state,
        cloud,
        actor,
        gate,
        privateDirectory: folder,
        wait,
        step: async (name, action) => {
          steps.push(name);
          return action();
        },
      });
    await f.state.arm(actor);
    const deadline = setTimeout(
      () => cancellation.abort(new Error(`Local preparation exceeded 30s at ${steps.at(-1)}`)),
      30000,
    );
    try {
      const preparing = withManagedGateSignal(cancellation.signal, () => phase('prepare'));
      if (fault === 'none') await preparing;
      else await assert.rejects(preparing, fault === 'interrupt' ? /interrupted dependency/ : /Command failed/);
    } catch (error) {
      t.diagnostic(JSON.stringify(f.requests.slice(-12).map((r) => ({ method: r.method, path: r.pathname }))));
      t.diagnostic(
        JSON.stringify(
          [...f.objects.values()]
            .filter((o) => o.kind === 'Deployment')
            .map((o) => ({
              name: o.metadata.name,
              generation: o.metadata.generation,
              replicas: o.spec.replicas,
              status: o.status,
            })),
        ),
      );
      throw error;
    } finally {
      clearTimeout(deadline);
      cancellation.abort();
      await gate.close();
      await waitForManagedGateCommands();
    }
    assert.equal(faultRequests, fault === 'none' ? 0 : 1, 'A failed/uncertain command must not be replayed');
    await phase('settle');
    await phase('cleanup');
    const cleanup = await phase('verifyCleanup');
    assert.equal(cleanup.uncertainWrites, 0);
    assert.equal((await f.state.read()).record.cleanupVerified, true);
    assert.ok(![...f.objects.values()].some((value) => value.metadata.namespace === namespace));
    assert.ok(f.objects.has(`/api/v1/namespaces/${settings().runnerNamespace}/pods/${actor.name}`));
    assert.ok(
      f.objects.has(
        `/apis/gateway.networking.k8s.io/v1/namespaces/${settings().gatewayNamespace}/gateways/${settings().gatewayName}`,
      ),
    );
    assert.deepEqual(errors, []);
    if (fault === 'none') {
      assert.ok(admitted.length >= 10, 'Both rendered releases must reach native admission');
      const summary = JSON.parse(await fs.readFile(path.join(folder, 'workload-admission-candidate.json')));
      assert.equal(summary.admitted[0].containers[0].resources.requests.cpu, '500m');
      assert.deepEqual(app.failures, []);
      assert.ok(app.requests.length >= 20);
      assert.ok(steps.includes('oauth') && steps.includes('inventory'));
    }
    t.diagnostic(
      JSON.stringify({ tools, nativeAdmissionWorkloads: admitted.length, steps, cleanup: cleanup.inventoryComplete }),
    );
  });
